import csv
from datetime import date

AUDIT = date(2026,3,31)

# Load licence register
licences = {}
with open('/app/input/licensed_property_register.csv') as f:
    for r in csv.DictReader(f):
        licences[r['license_id']] = r

# Build supersession map: superseded_id -> superseding_id
supersede = {}
for lid, row in licences.items():
    if row['supersedes'] and row['supersedes'] != 'none':
        supersede[row['supersedes']] = lid

def effective(lid):
    """Return (license_type, covers_distribution, valid_until) governing a cited licence id."""
    if lid == 'none' or lid not in licences:
        return None
    # if this id is superseded, use superseding row's terms
    gov = lid
    if lid in supersede:
        gov = supersede[lid]
    g = licences[gov]
    return (g['license_type'], g['covers_distribution'], g['valid_until'])

def covers(lid, use_type, dist):
    eff = effective(lid)
    if eff is None:
        return False
    ltype, cdist, vuntil = eff
    if ltype != use_type:
        return False
    covers_list = cdist.split(';')
    if 'all' not in covers_list and dist not in covers_list:
        return False
    if date.fromisoformat(vuntil) < AUDIT:
        return False
    return True

accounts = {}
with open('/app/input/client_accounts.csv') as f:
    for r in csv.DictReader(f):
        accounts[r['account_id']] = r

requests = []
with open('/app/input/composite_request_log.csv') as f:
    for r in csv.DictReader(f):
        requests.append(r)

results = {}
acct_counts = {}

for r in requests:
    rid = r['request_id']
    if r['intake_status'] == 'withdrawn':
        continue
    acc = accounts[r['account_id']]
    dist = r['intended_distribution']
    findings = []

    # §3 character
    if r['character_property'] != 'none':
        char_lic = r['character_license_id']
        cleared_lic = covers(char_lic, 'character', dist) if char_lic != 'none' else False
        cleared_allow = (dist == 'personal_only')
        if not (cleared_lic or cleared_allow):
            findings.append('UNLICENSED_CHARACTER_USE')

    # §4 background
    bs = r['background_source']
    if bs == 'customer_original':
        pass
    elif bs == 'third_party_unlicensed':
        findings.append('THIRD_PARTY_BACKGROUND_UNLICENSED')
    elif bs == 'third_party_licensed':
        blic = r['background_license_id']
        if not covers(blic, 'background', dist):
            findings.append('THIRD_PARTY_BACKGROUND_UNLICENSED')

    # §5 minor consent
    if r['subject_is_minor'] == 'True':
        ct = r['minor_consent_type']
        present = ct != 'none'
        current = r['minor_consent_valid_until'] != 'none' and date.fromisoformat(r['minor_consent_valid_until']) >= AUDIT
        if ct == 'publicity':
            wide = True
        elif ct == 'basic':
            wide = dist in ('personal_only','client_internal')
        else:
            wide = False
        if not (present and current and wide):
            findings.append('MISSING_MINOR_CONSENT')

    # §6 commercial distribution
    if dist in ('social_public','print_for_sale'):
        active = acc['agreement_status'] == 'active'
        cov = acc['master_agreement_covers']
        named = cov != 'none' and dist in cov.split(';')
        if not (active and named):
            findings.append('COMMERCIAL_DISTRIBUTION_FLAG')

    # §7 alteration disclosure
    if r['alteration_level'] == 'substantive' and dist in ('social_public','print_for_sale'):
        if r['alteration_disclosure_on_file'] != 'True':
            findings.append('ALTERATION_DISCLOSURE_MISSING')

    finding_str = '|'.join(findings) if findings else 'none'
    results[rid] = findings

    a = r['account_id']
    acct_counts.setdefault(a, {'req':0,'flag':0,'maxf':0})
    acct_counts[a]['req'] += 1
    if findings:
        acct_counts[a]['flag'] += 1
    acct_counts[a]['maxf'] = max(acct_counts[a]['maxf'], len(findings))

    print(f"{rid}: {finding_str}")

print("\n--- accounts ---")
total_req = sum(v['req'] for v in acct_counts.values())
total_flag = sum(v['flag'] for v in acct_counts.values())
batch_share = total_flag/total_req
print(f"audited={total_req} flagged={total_flag} batch_share={batch_share:.4f}")
for a in sorted(acct_counts):
    v = acct_counts[a]
    share = v['flag']/v['req'] if v['req'] else 0
    esc = (share > batch_share) or (v['maxf'] >= 3)
    print(f"{a}: type={accounts[a]['account_type']} req={v['req']} flag={v['flag']} maxf={v['maxf']} share={share:.4f} esc={esc}")

# per-finding counts
from collections import Counter
c = Counter()
total_findings = 0
for fset in results.values():
    for f in fset:
        c[f]+=1
        total_findings+=1
print("\n--- finding counts ---")
for k in ['UNLICENSED_CHARACTER_USE','THIRD_PARTY_BACKGROUND_UNLICENSED','MISSING_MINOR_CONSENT','COMMERCIAL_DISTRIBUTION_FLAG','ALTERATION_DISCLOSURE_MISSING']:
    print(f"{k}: {c[k]}")
print("total_findings:", total_findings)
print("flagged_count:", total_flag)
print("compliant:", total_req - total_flag)
print("escalated:", sum(1 for a in acct_counts if (acct_counts[a]['flag']/acct_counts[a]['req'] > batch_share) or acct_counts[a]['maxf']>=3))
